mapper.select:
SELECT BOARD_NO as boardNo, BOARD_TITLE as title, CATEGORY, COOK_TIME as cookTime, OPEN as open, LIKES_COUNT as likesCount, BOARD_POSTDATE as boardPostdate, CASE WHEN CATEGORY = '한식' THEN 'thumb-green' WHEN CATEGORY = '양식' THEN 'thumb-salmon' WHEN CATEGORY = '일식' THEN 'thumb-blue' WHEN CATEGORY = '분식' THEN 'thumb-peach' ELSE 'thumb-mint' END as thumbClass FROM BOARD WHERE USER_NO = #{userNo} AND BOARD_DELETE = 'N'
AND CATEGORY = #{category}
ORDER BY BOARD_POSTDATE DESC

SELECT B.BOARD_NO as boardNo, B.BOARD_TITLE as title, B.CATEGORY as category, B.COOK_TIME as cookTime, B.LIKES_COUNT as likesCount, M.NICKNAME as authorNickname, CASE WHEN B.CATEGORY = '한식' THEN 'thumb-green' WHEN B.CATEGORY = '양식' THEN 'thumb-salmon' ELSE 'thumb-peach' END as thumbClass FROM SCRAP S JOIN BOARD B ON S.BOARD_NO = B.BOARD_NO JOIN USER M ON B.USER_NO = M.USER_NO WHERE S.USER_NO = #{userNo} AND B.BOARD_DELETE = 'N'
AND B.CATEGORY = #{category}
ORDER BY S.SCRAP_DATE DESC

mapper.update:
UPDATE USER

    NICKNAME = #{nickname},
    INTRODUCE = #{introduce},
    PROFILE_IMAGE_URL = #{profileImageUrl}

WHERE USER_NO = #{userNo}

UPDATE USER 
SET WITHDRAW = 'Y' 
WHERE USER_NO = #{userNo}
